"""Bounded finite Pass C tests for Lord_Xander__the_Collector (Deck 30). Part A: seeded finite Monte Carlo goldfish of
commander deployment (seed 30, fixed N, on the play, no mulligans, no opponent, paired common random numbers: each
challenger replaces the cut card at the same library position). Part B: exhaustive finite rules-encoded scenario grids.
Neither part is a win-rate simulation."""
import json,re,random,itertools,collections
W='/workspace/d30w/'
def load(p):
    out=[]
    for l in open(p):
        m=re.match(r'(\d+)x (.+?)( \[Commander\])?$',l.strip())
        if m and not m.group(3): out+=[m.group(2)]*int(m.group(1))
    return out
base=load(W+'base.txt'); assert len(base)==99
def swap(d,pairs):
    d=d[:]
    for a,c in pairs: d[d.index(c)]=a
    return d
NEC=("Necromancy","Persist"); BOOTS=("Swiftfoot Boots","Lightning Greaves"); MAL=("Malakir Rebirth // Malakir Mire","Bojuka Bog")
FINAL=[NEC,BOOTS,MAL]
def key(a,c): return f"plus_{a.split(' // ')[0]}_minus_{c}".replace(' ','_').replace("'",'').replace(',','')
CFG={"baseline":base}
for a,c in FINAL: CFG["single_"+key(a,c)]=swap(base,[(a,c)])
CFG["candidate"]=swap(base,FINAL)
PROBES=[("Chrome Mox","Talisman of Creativity"),("Command Beacon","Xander's Lounge"),("Glasspool Mimic // Glasspool Shore","Training Center"),
        ("Kiki-Jiki, Mirror Breaker","Karlach, Fury of Avernus"),("Seize the Day","Karlach, Fury of Avernus")]
for a,c in PROBES: CFG["probe_on_candidate_"+key(a,c)]=swap(CFG["candidate"],[(a,c)] if c in CFG["candidate"] else [])
CFG["PassC_single_plus_Goryos_Vengeance_minus_Persist_on_baseline"]=swap(base,[("Goryo's Vengeance","Persist")])
CFG["alt_A_owner_keeps_Necromancy_minus_Karlach"]=swap(base,[("Necromancy","Karlach, Fury of Avernus"),BOOTS,MAL])
CFG["alt_B_owner_keeps_Necromancy_minus_An_Offer_You_Cant_Refuse"]=swap(base,[("Necromancy","An Offer You Can't Refuse"),BOOTS,MAL])
# ---- mana model
ANY="UBR"
LAND={"Island":("U",0),"Swamp":("B",0),"Mountain":("R",0),"Badlands":("BR",0),"Blood Crypt":("BR",0),"Steam Vents":("UR",0),"Watery Grave":("UB",0),
 "Underground Sea":("UB",0),"Volcanic Island":("UR",0),"Bloodstained Mire":(ANY,0),"Polluted Delta":(ANY,0),"Scalding Tarn":(ANY,0),"Marsh Flats":(ANY,0),
 "Flooded Strand":(ANY,0),"Prismatic Vista":(ANY,0),"Command Tower":(ANY,0),"Mana Confluence":(ANY,0),"City of Brass":(ANY,0),
 "Luxury Suite":("BR",0),"Morphic Pool":("UB",0),"Training Center":("UR",0),"Haunted Ridge":("BR","ridge"),"Xander's Lounge":(ANY,1),
 "Bojuka Bog":("B",1),"Malakir Rebirth // Malakir Mire":("B",1),"Glasspool Mimic // Glasspool Shore":("U",1),"Otawara, Soaring City":("U",0),
 "Takenuma, Abandoned Mire":("B",0),"Hall of Echoes":("C",0),"Urza's Saga":("C",0),"Command Beacon":("C",0),"Hall of the Bandit Lord":("H",1),"Ancient Tomb":("CC",0)}
ROCK={"Sol Ring":(1,["C","C"]),"Arcane Signet":(2,[ANY]),"Talisman of Creativity":(2,["UR"]),"Talisman of Dominance":(2,["UB"]),"Talisman of Indulgence":(2,["BR"])}
ONESHOT={"Mana Vault":(1,["C","C","C"]),"Grim Monolith":(2,["C","C","C"])}
HASTE_EQ={"Lightning Greaves":0,"Swiftfoot Boots":1}
def pay(srcs,need_col,g):
    s=srcs[:]
    if len(s)<len(need_col)+g: return None
    order=sorted(range(len(s)),key=lambda j:len(s[j]) if s[j] not in("C","H") else 0)
    used=set()
    def dfs(i,used):
        if i==len(need_col): return used
        for j in sorted(range(len(s)),key=lambda j:len(s[j])):
            if j not in used and need_col[i] in s[j]: 
                r=dfs(i+1,used|{j})
                if r is not None: return r
        return None
    u=dfs(0,frozenset())
    if u is None: return None
    rest=[j for j in order if j not in u]
    if len(rest)<g: return None
    return set(u)|set(rest[:g])
def game(deck,rnd,T=7):
    d=deck[:]; rnd.shuffle(d); hand=d[:7]; lib=d[7:]
    lands=[]; rocks=[]; eq=[]; xt=None; xh=False; recs=[]; oneshot_used=set()
    for t in range(1,T+1):
        if t>1: hand.append(lib.pop(0))
        lh=[c for c in hand if c in LAND]; newtapped=False
        def untapped(c):
            k=LAND[c][1]
            if k=="ridge": return len(lands)>=2
            return k==0
        if lh:
            pref=sorted(lh,key=lambda c:((0 if not untapped(c) else 1) if t<=2 else (0 if untapped(c) else 1), c=="Command Beacon"))
            L=pref[0]; hand.remove(L); newtapped=not untapped(L); lands.append(L)
        srcs=[]
        for i,x in enumerate(lands):
            if i==len(lands)-1 and newtapped: continue
            v=LAND[x][0]
            if v=="CC": srcs+=["C","C"]
            else: srcs.append(v)
        for r in rocks: srcs+=ROCK[r][1] if r in ROCK else ["ANYMOX"]
        avail=[("UBR" if x=="ANYMOX" else x) for x in srcs]
        # rocks first (cheapest), Chrome Mox imprints a nonland nonartifact card if one is spare
        for r in sorted([c for c in hand if c in ROCK or c in ONESHOT or c=="Chrome Mox"],key=lambda c:(ROCK.get(c) or ONESHOT.get(c) or (0,))[0]):
            if r=="Chrome Mox":
                spare=[c for c in hand if c not in LAND and c not in ROCK and c not in ONESHOT and c not in("Chrome Mox","Lotus Petal","Dark Ritual","Lion's Eye Diamond") and c not in HASTE_EQ]
                if spare: hand.remove(r); hand.remove(spare[0]); rocks.append("Chrome Mox"); avail.append("UBR")
                continue
            cost,prod=(ROCK.get(r) or ONESHOT.get(r))
            u=pay(avail,[],cost)
            if u is None: continue
            avail=[x for j,x in enumerate(avail) if j not in u]; hand.remove(r)
            if r in ROCK: rocks.append(r); avail+=prod
            else: avail+=prod   # Mana Vault / Grim Monolith: one burst the turn they land (no untap modelled)
        if xt is None:
            extra=[]
            if "Lotus Petal" in hand: extra.append(("Lotus Petal",["UBR"]))
            if "Dark Ritual" in hand: extra.append(("Dark Ritual","RIT"))
            if "Lion's Eye Diamond" in hand: extra.append(("Lion's Eye Diamond",["UBR"]*3))
            pool=avail[:]
            usedx=[]
            for n,p in extra:
                if p=="RIT":
                    u=pay(pool,["B"],0)
                    if u is None: continue
                    pool=[x for j,x in enumerate(pool) if j not in u]+["B","B","B"]
                else: pool=pool+p
                usedx.append(n)
                if pay([("C" if x=="H" else x) for x in pool],["U","B","R"],4) is not None: break
            P=[("C" if x=="H" else x) for x in pool]
            u=pay(P,["U","B","R"],4)
            if u is not None:
                xt=t; rem=[x for j,x in enumerate(pool) if j not in u]
                for n in usedx: hand.remove(n)
                bandit = "H" in [pool[j] for j in u]
                if not bandit and "H" in rem:  # re-solve preferring the Bandit Lord mana for haste
                    pre=[j for j,x in enumerate(pool) if x=="H"][0]
                    P2=[x for j,x in enumerate(P) if j!=pre]; u2=pay(P2,["U","B","R"],3)
                    if u2 is not None:
                        bandit=True; idx=[j for j in range(len(pool)) if j!=pre]; rem=[pool[idx[j]] for j in range(len(P2)) if j not in u2]
                xh=bandit
                for e in [c for c in eq]:
                    if not xh and len(rem)>=HASTE_EQ[e]: xh=True; rem=rem[HASTE_EQ[e]:]
                for e in [c for c in hand if c in HASTE_EQ]:
                    if not xh and len(rem)>=2+HASTE_EQ[e]: xh=True; hand.remove(e); eq.append(e); rem=rem[2+HASTE_EQ[e]:]
                avail=rem
        for e in [c for c in hand if c in HASTE_EQ]:
            u=pay(avail,[],2)
            if u is not None: avail=[x for j,x in enumerate(avail) if j not in u]; hand.remove(e); eq.append(e)
        recs.append(dict(cast=xt is not None, attack=xt is not None and (xt<t or xh), haste_same_turn=xt==t and xh))
    return recs
def run(deck,seed=30,N=20000,T=7):
    rnd=random.Random(seed); acc=collections.defaultdict(collections.Counter)
    for _ in range(N):
        for t,o in enumerate(game(deck,rnd,T),1):
            for k,v in o.items(): acc[t][k]+=v
    return {f"turn {t}":{"P_Xander_cast":round(a['cast']/N,4),"P_Xander_attack_trigger_declared":round(a['attack']/N,4),"P_Xander_haste_attack_on_cast_turn_by_this_turn":round(a['haste_same_turn']/N,4)} for t,a in acc.items()}

# ---------------- Part B: exhaustive finite rules-encoded grids
def gridB():
    B={}
    # B1 recursion slot: Persist vs Necromancy vs Goryo's Vengeance
    TG={"Lord_Xander_own_graveyard":dict(own=True,leg=True,xander=True),
        "Tergrid_or_Karlach_or_Bruvac_own_graveyard":dict(own=True,leg=True,xander=False),
        "Spark_Double_or_Auton_Soldier_card_own_graveyard_Xander_on_battlefield":dict(own=True,leg=False,xander=False,clone=True),
        "Notion_Thief_or_Opposition_Agent_or_Orcish_Bowmasters_own_graveyard":dict(own=True,leg=False,xander=False),
        "opponent_creature_card_milled_by_Xander":dict(own=False,leg=False,xander=False),
        "opponent_legendary_creature_card_milled_by_Xander":dict(own=False,leg=True,xander=False)}
    MANA=[1,2,3]; TIMING=["own_precombat_main","opponent_end_step_or_in_response"]
    def res(card,tg,m,ti):
        t=TG[tg]; r=dict(returns=False,etb=False,attack_trigger_this_turn=False,extra_dies_trigger=False,stays=False)
        if card=="Persist":
            if m<2 or ti!="own_precombat_main" or not t["own"] or t["leg"]: return r
            r.update(returns=True,etb=True,stays=True); return r
        if card=="Goryo's Vengeance":
            if m<2 or not t["own"] or not t["leg"]: return r
            r.update(returns=True,etb=True,attack_trigger_this_turn=(t["xander"] and ti=="own_precombat_main")); return r   # exiled at end step: no dies trigger
        if card=="Necromancy":
            if m<3: return r
            off=ti!="own_precombat_main"
            r.update(returns=True,etb=True,stays=not off,extra_dies_trigger=(off and t["xander"])); return r
        return r
    g=collections.Counter(); cells=0; rows=[]
    for tg,m,ti in itertools.product(TG,MANA,TIMING):
        cells+=1; o={c:res(c,tg,m,ti) for c in("Persist","Necromancy","Goryo's Vengeance")}
        for c,v in o.items():
            k=c.replace(' ','_').replace("'",'')
            for kk,vv in v.items(): g[k+'_'+kk]+=vv
        g['Necromancy_returns_Persist_does_not']+=o["Necromancy"]["returns"] and not o["Persist"]["returns"]
        g['Persist_returns_Necromancy_does_not']+=o["Persist"]["returns"] and not o["Necromancy"]["returns"]
        g['Goryos_returns_Necromancy_does_not']+=o["Goryo's Vengeance"]["returns"] and not o["Necromancy"]["returns"]
        rows.append(dict(target=tg,mana=m,timing=ti,**{c:v for c,v in o.items()}))
    B["B1_recursion_Persist_vs_Necromancy_vs_Goryos"]=dict(cells=cells,**g,rows=rows,notes="Frozen-cache Oracle: Persist returns target NONLEGENDARY creature card from YOUR graveyard (sorcery, -1/-1 counter), so it can never return Lord Xander, Tergrid, Karlach or Bruvac. Necromancy ({2}{B}, castable as though it had flash) returns a creature card from ANY graveyard; cast off sorcery timing it is sacrificed at the next cleanup step, its leaves trigger sacrifices the creature, so an end-step Necromancy on Lord Xander yields the enters (discard half) AND a second dies (sacrifice half) trigger. Goryo's Vengeance returns only a legendary card from your graveyard with haste, exiled (not dies) at the next end step. Commander replacement: Lord Xander must have been put into the graveyard (owner's choice) to be a target. Unweighted cells, not frequencies.")
    # B2 haste equipment: Lightning Greaves (shroud, equip 0) vs Swiftfoot Boots (hexproof, equip 1) attached to Lord Xander
    ACT=["none_just_attack","equip_Helm_of_the_Host_to_Xander","equip_Sword_of_Feast_and_Famine_to_Xander","equip_Blade_of_Selves_to_Xander",
         "Saw_in_Half_own_Xander","Molten_Duplication_own_Xander","Feign_Death_own_Xander","Malakir_Rebirth_own_Xander","Necromancy_or_Animate_Dead_unaffected_card_in_graveyard",
         "opponent_targeted_removal_on_Xander","opponent_wrath_or_edict"]
    OTHER=["another_creature_you_control","no_other_creature"]; SPARE=[0,1]
    def eqres(card,a,o,sp):
        own=a not in("none_just_attack","Necromancy_or_Animate_Dead_unaffected_card_in_graveyard","opponent_targeted_removal_on_Xander","opponent_wrath_or_edict")
        haste_ok = card=="Lightning Greaves" or sp>=1
        if a=="opponent_targeted_removal_on_Xander": return dict(action_ok=True,protected=True,haste=haste_ok)
        if a=="opponent_wrath_or_edict": return dict(action_ok=True,protected=False,haste=haste_ok)
        if own and card=="Lightning Greaves":
            # shroud stops your own targeting; Greaves can be moved off with Equip {0} only onto another creature you control (sorcery speed), losing haste/shroud on Xander
            ok=o=="another_creature_you_control" and not a.startswith(("Feign","Malakir"))  or (o=="another_creature_you_control" and a.startswith(("Feign","Malakir")))
            return dict(action_ok=ok,protected=not ok,haste=haste_ok,needs_reequip_away=ok)
        return dict(action_ok=True,protected=True,haste=haste_ok,needs_reequip_away=False)
    g=collections.Counter(); cells=0; rows=[]
    for a,o,sp in itertools.product(ACT,OTHER,SPARE):
        cells+=1; gr=eqres("Lightning Greaves",a,o,sp); bo=eqres("Swiftfoot Boots",a,o,sp)
        g['Greaves_action_ok']+=gr["action_ok"]; g['Boots_action_ok']+=bo["action_ok"]; g['Greaves_haste']+=gr["haste"]; g['Boots_haste']+=bo["haste"]
        g['Boots_ok_Greaves_blocked']+=bo["action_ok"] and not gr["action_ok"]; g['Greaves_ok_Boots_blocked']+=gr["action_ok"] and not bo["action_ok"]
        g['Greaves_must_strip_own_protection']+=gr.get("needs_reequip_away",False)
        g['Greaves_haste_Boots_no_haste']+=gr["haste"] and not bo["haste"]
        rows.append(dict(action=a,other=o,spare_mana_after_Xander=sp,greaves=gr,boots=bo))
    B["B2_haste_equipment_Greaves_vs_Boots"]=dict(cells=cells,**g,rows=rows,notes="Lightning Greaves: haste and shroud, Equip {0}. Swiftfoot Boots: haste and hexproof, Equip {1}. Equip, Saw in Half, Molten Duplication, Feign Death and Malakir Rebirth all target; shroud stops your own targeting, hexproof stops only opponents. With Greaves on Lord Xander you can enable the action only by moving Greaves to another creature you control (Equip {0}, sorcery speed), which strips Xander's protection and is impossible for instant-speed responses with no other creature (encoded conservatively as allowed when another creature exists). Boots costs 1 more to grant haste the turn Xander is cast (spare 0 cells). Phantasmal Image copies are sacrificed if either is equipped to them.")
    # B3 land slot: Bojuka Bog vs Malakir Rebirth // Malakir Mire
    ST=["opponent_destroys_Xander","opponent_edict_or_sacrifice","opponent_wrath_destroy","opponent_exiles_or_bounces_Xander","own_Altar_of_Dementia_sacrifice_Xander",
        "opponent_graveyard_combo_Breach_or_reanimator","opponent_flashback_or_escape_value","no_event_need_land_drop"]
    MB=["B_open","no_B_open"]
    def land(card,s,m):
        if s=="no_event_need_land_drop": return dict(answers=True,note="both enter tapped and tap for {B}")
        if card=="Bojuka Bog": return dict(answers=s.startswith("opponent_graveyard") or s.startswith("opponent_flashback"),note="exile one graveyard on entry (needs to be held as the land drop)")
        if s in("opponent_destroys_Xander","opponent_edict_or_sacrifice","opponent_wrath_destroy","own_Altar_of_Dementia_sacrifice_Xander"):
            return dict(answers=m=="B_open",note="dies trigger (sacrifice half) then returns tapped: enters trigger (discard half); Xander stays on the battlefield")
        return dict(answers=False,note="exile/bounce or graveyard issue: no help")
    g=collections.Counter(); cells=0; rows=[]
    for s,m in itertools.product(ST,MB):
        cells+=1; b=land("Bojuka Bog",s,m); r=land("Malakir Rebirth // Malakir Mire",s,m)
        g['Bog_answers']+=b["answers"]; g['Malakir_answers']+=r["answers"]; g['Malakir_only']+=r["answers"] and not b["answers"]; g['Bog_only']+=b["answers"] and not r["answers"]
        rows.append(dict(state=s,mana=m,bojuka_bog=b,malakir=r))
    B["B3_land_slot_Bojuka_Bog_vs_Malakir_Rebirth"]=dict(cells=cells,**g,rows=rows,notes="Malakir Rebirth ({B} instant, lose 2 life): target creature gains 'when this dies, return it to the battlefield tapped' until end of turn; its back face Malakir Mire enters tapped for {B}, same as Bojuka Bog. Graveyard-hate loss (Bog_only cells) is the disclosed cost; the deck keeps no other repeatable graveyard hate (Tergrid's Lantern is not hate). Xander dying must be routed to the graveyard (decline the command-zone replacement) for the return.")
    return B
if __name__=="__main__":
    import sys
    A={k:run(d) for k,d in CFG.items()}
    B=gridB(); json.dump({'A':A,'B':B},open(W+'meas30.json','w'),indent=1)
    for k,v in B.items(): print(k,{a:b for a,b in v.items() if a not in('notes','rows')})
    for k,v in A.items(): print(k[:70].ljust(70),{t[5:]:(r['P_Xander_cast'],r['P_Xander_attack_trigger_declared']) for t,r in v.items() if t in('turn 4','turn 5','turn 6','turn 7')})
